"""Fast NSGA-II for Fe-Ni Invar. 2 models, 1 repeat, smaller pop."""
import os, warnings, time, json
os.environ['OMP_NUM_THREADS']='4'
warnings.filterwarnings('ignore')
import numpy as np, itertools
from pathlib import Path
from deepmd.infer import DeepEval

ELEMENTS = ['Fe','Ni','Al','Ti','Si','Mn','Co','Cr']
AMASS = {'Fe':55.845,'Ni':58.693,'Al':26.982,'Ti':47.867,'Si':28.086,'Mn':54.938,'Co':58.933,'Cr':51.996}
AVOL  = {'Fe':11.78,'Ni':10.94,'Al':16.60,'Ti':17.65,'Si':12.06,'Mn':12.21,'Co':11.12,'Cr':12.28}
TIDX  = {'Fe':25,'Ni':27,'Al':12,'Ti':21,'Si':13,'Mn':24,'Co':26,'Cr':23}
BOUNDS = {'Ni':(0.28,0.38),'Al':(0.00,0.03),'Ti':(0.00,0.02),'Si':(0.00,0.08),'Mn':(0.00,0.05),'Co':(0.00,0.06),'Cr':(0.00,0.04)}
FE_MIN,FE_MAX = 0.50,0.70
NA = 32

def density(c):
    m=sum(c[e]*AMASS[e] for e in ELEMENTS)
    v=sum(c[e]*AVOL[e] for e in ELEMENTS)
    return m/(v*1e-24*6.022e23)

# Pre-compute FCC positions template
_a0 = 3.59
_cell0 = np.diag([2*_a0]*3)
_basis = np.array([[0,0,0],[.5,.5,0],[.5,0,.5],[0,.5,.5]])
_pos_frac = []
for ix,iy,iz in itertools.product(range(2),repeat=3):
    for b in _basis:
        _pos_frac.append((np.array([ix,iy,iz])+b)/2)
_pos_frac = np.array(_pos_frac)

def predict(models, c):
    avg_v = sum(c[e]*AVOL[e] for e in ELEMENTS)
    a = (4*avg_v)**(1/3)
    cell = np.diag([2*a]*3)
    pos = _pos_frac @ cell
    # assign types
    rem=NA; counts={}
    for e in ELEMENTS[1:]:
        n=min(int(round(c[e]*NA)),rem); counts[e]=n; rem-=n
    counts['Fe']=rem
    types=[]
    for e in ELEMENTS: types+=[TIDX[e]]*counts.get(e,0)
    types=np.array(types)
    np.random.shuffle(types)
    coords=pos.reshape(1,-1); cells=cell.reshape(1,-1)
    vals=[float(dp.eval(coords,cells,types)[0].flatten()[0]) for dp in models]
    return np.mean(vals)

def rand_comp(rng):
    for _ in range(1000):
        c={e:rng.uniform(*BOUNDS[e]) for e in ELEMENTS[1:]}
        fe=1-sum(c.values())
        if FE_MIN<=fe<=FE_MAX: c['Fe']=fe; return c
    raise RuntimeError

def xover(p1,p2,rng):
    a=rng.uniform(0,1)
    c={e:a*p1[e]+(1-a)*p2[e] for e in ELEMENTS[1:]}
    fe=1-sum(c.values())
    if FE_MIN<=fe<=FE_MAX: c['Fe']=fe; return c
    return dict(p1)

def mut(c,rng,rate=0.3,sig=0.01):
    nc=dict(c)
    for e in ELEMENTS[1:]:
        if rng.random()<rate: nc[e]=np.clip(nc[e]+rng.normal(0,sig),*BOUNDS[e])
    fe=1-sum(nc[e] for e in ELEMENTS[1:])
    if FE_MIN<=fe<=FE_MAX: nc['Fe']=fe; return nc
    return c

def dom(a,b): return all(ai<=bi for ai,bi in zip(a,b)) and any(ai<bi for ai,bi in zip(a,b))

def nds(O):
    n=len(O);dc=[0]*n;ds=[[] for _ in range(n)];F=[[]];R=[0]*n
    for i in range(n):
        for j in range(n):
            if i==j:continue
            if dom(O[i],O[j]):ds[i].append(j)
            elif dom(O[j],O[i]):dc[i]+=1
        if dc[i]==0:R[i]=0;F[0].append(i)
    k=0
    while F[k]:
        nf=[]
        for i in F[k]:
            for j in ds[i]:
                dc[j]-=1
                if dc[j]==0:R[j]=k+1;nf.append(j)
        k+=1;F.append(nf)
    return F[:-1],R

def cdist(O,fr):
    n=len(fr)
    if n<=2:return[1e18]*n
    d=[0.]*n
    for m in range(2):
        si=sorted(range(n),key=lambda i:O[fr[i]][m])
        d[si[0]]=d[si[-1]]=1e18
        r=O[fr[si[-1]]][m]-O[fr[si[0]]][m]
        if r==0:continue
        for i in range(1,n-1):d[si[i]]+=(O[fr[si[i+1]]][m]-O[fr[si[i-1]]][m])/r
    return d

if __name__=='__main__':
    print("Loading 2 surrogate models...")
    models=[DeepEval(f'models/tec_{i}.pt') for i in [0,2]]
    print("Models loaded.\n")

    POP=60; NGEN=30
    rng=np.random.default_rng(42)
    pop=[rand_comp(rng) for _ in range(POP)]

    t0=time.time()
    objs=[(predict(models,c),density(c)) for c in pop]
    print(f"Init eval: {time.time()-t0:.1f}s")

    for gen in range(NGEN):
        gt=time.time()
        off=[]
        while len(off)<POP:
            i1,i2=rng.integers(0,POP,2);i3,i4=rng.integers(0,POP,2)
            p1=pop[i1] if objs[i1]<objs[i2] else pop[i2]
            p2=pop[i3] if objs[i3]<objs[i4] else pop[i4]
            off.append(mut(xover(p1,p2,rng),rng))
        oobjs=[(predict(models,c),density(c)) for c in off]
        cpop=pop+off;cobjs=objs+oobjs
        fronts,_=nds(cobjs)
        npop=[];nobjs=[]
        for fr in fronts:
            if len(npop)+len(fr)<=POP:
                for i in fr:npop.append(cpop[i]);nobjs.append(cobjs[i])
            else:
                cd=cdist(cobjs,fr)
                si=sorted(range(len(fr)),key=lambda i:cd[i],reverse=True)
                for i in si[:POP-len(npop)]:npop.append(cpop[fr[i]]);nobjs.append(cobjs[fr[i]])
                break
        pop=npop;objs=nobjs
        if gen%5==0 or gen==NGEN-1:
            fronts2,_=nds(objs);pf=fronts2[0]
            ts=[objs[i][0] for i in pf];ds=[objs[i][1] for i in pf]
            print(f"Gen {gen:3d} | PF={len(pf):3d} | TEC=[{min(ts):.2f},{max(ts):.2f}] | ρ=[{min(ds):.3f},{max(ds):.3f}] | {time.time()-gt:.1f}s")

    # Final Pareto with full 5-model ensemble
    print("\nRe-evaluating Pareto front with full 5-model ensemble...")
    all_models=[DeepEval(f'models/tec_{i}.pt') for i in range(5)]
    fronts,_=nds(objs);pf=fronts[0]
    results=[]
    for idx in pf:
        c=pop[idx]
        # 5 models × 2 random structures
        vals=[]
        for rep in range(2):
            avg_v=sum(c[e]*AVOL[e] for e in ELEMENTS)
            a=(4*avg_v)**(1/3)
            cell=np.diag([2*a]*3)
            pos=_pos_frac@cell
            rem=NA;counts={}
            for e in ELEMENTS[1:]:
                n=min(int(round(c[e]*NA)),rem);counts[e]=n;rem-=n
            counts['Fe']=rem
            types=[]
            for e in ELEMENTS:types+=[TIDX[e]]*counts.get(e,0)
            types=np.array(types)
            np.random.seed(rep*100+idx)
            np.random.shuffle(types)
            coords=pos.reshape(1,-1);cells=cell.reshape(1,-1)
            for dp in all_models:
                vals.append(float(dp.eval(coords,cells,types)[0].flatten()[0]))
        results.append({
            'comp':{e:round(c[e]*100,2) for e in ELEMENTS},
            'tec_mean':round(np.mean(vals),3),
            'tec_std':round(np.std(vals),3),
            'density':round(density(c),4)
        })
    results.sort(key=lambda x:x['tec_mean'])

    print(f"\n{'='*95}")
    print(f"PARETO-OPTIMAL CANDIDATES ({len(results)} solutions)")
    print(f"{'='*95}")
    hdr=f"{'#':>3} {'TEC':>8} {'±σ':>6} {'ρ':>8}"
    for e in ELEMENTS:hdr+=f" {e:>6}"
    print(hdr);print('-'*95)
    for i,r in enumerate(results):
        ln=f"{i+1:3d} {r['tec_mean']:8.3f} {r['tec_std']:6.3f} {r['density']:8.4f}"
        for e in ELEMENTS:ln+=f" {r['comp'][e]:6.2f}"
        print(ln)

    with open('pareto_results.json','w') as f:
        json.dump(results,f,indent=2)
    print(f"\nTotal time: {time.time()-t0:.0f}s")
    print("Saved to pareto_results.json")
